import{_ as t,o as n,c as s,al as o}from"./chunks/framework.7vp1BMOE.js";const m=JSON.parse('{"title":"get_mode_requirements","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/get_mode_requirements/CLAUDE.md","filePath":"scripts/get_mode_requirements/CLAUDE.md"}'),a={name:"scripts/get_mode_requirements/CLAUDE.md"};function i(d,e,r,c,p,l){return n(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="get-mode-requirements" tabindex="-1">get_mode_requirements <a class="header-anchor" href="#get-mode-requirements" aria-label="Permalink to &quot;get_mode_requirements&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p><code>get_mode_requirements.py</code> parses the PX4 flight mode requirements defined in <code>src/modules/commander/ModeUtil/mode_requirements.cpp</code> and generates Markdown documentation.</p><p>It produces two kinds of output under <code>docs/en/</code>:</p><ul><li><code>flight_modes/mode_requirements.md</code> — a consolidated overview table for all vehicle types.</li><li>Per-mode requirement text injected directly into individual flight-mode pages using include markers.</li></ul><h2 id="running" tabindex="-1">Running <a class="header-anchor" href="#running" aria-label="Permalink to &quot;Running&quot;">​</a></h2><p>From the repo root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/get_mode_requirements/get_mode_requirements.py</span></span></code></pre></div><p>Or from the <code>docs/</code> directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/get_mode_requirements/get_mode_requirements.py</span></span></code></pre></div><h2 id="inline-injection" tabindex="-1">Inline Injection <a class="header-anchor" href="#inline-injection" aria-label="Permalink to &quot;Inline Injection&quot;">​</a></h2><p>The script locates each parent flight-mode doc (e.g. <code>flight_modes_fw/manual.md</code>) by scanning <code>docs/en/flight_modes/</code>, <code>docs/en/flight_modes_fw/</code>, <code>docs/en/flight_modes_mc/</code>, and <code>docs/en/advanced_features/</code> for a VitePress <code>&lt;!--@include:--&gt;</code> directive (or an existing <code>AUTO-GENERATED</code> sentinel block) that references the corresponding snippet name (<code>build_snippet_to_parent_map()</code>). This directory scan is what actually determines where a mode&#39;s requirements get injected — it is <strong>independent</strong> of the <code>doc</code> field in <code>mode_nav_state_defns.json</code>, which only controls headings/links in <code>mode_requirements.md</code>. A mode can have a <code>doc</code> pointing at a page that isn&#39;t scanned (or has no injection marker on it yet) and still trigger a &quot;not mapped to a doc&quot; warning; fix this by adding an <code>&lt;!-- AUTO-GENERATED: snippet_stem --&gt;&lt;!-- END AUTO-GENERATED: snippet_stem --&gt;</code> marker pair (content between them can be empty — the script fills it in) to the actual doc page, and if that page lives outside the four scanned directories, add its directory to <code>search_dirs</code> in <code>build_snippet_to_parent_map()</code>.</p><p>A single doc page can contain multiple injection points for different nav-states (e.g. <code>flight_modes/offboard.md</code> has one per vehicle type; <code>flight_modes_mc/manual_stabilized.md</code> has one for <code>NAVIGATION_STATE_STAB</code> and one for <code>NAVIGATION_STATE_MANUAL</code>, since those are distinct nav-states with different requirements that happen to share one doc page). Each generated block always starts its own <code>### Mode Requirements</code> heading, so when adding a second block to the same page, add distinguishing surrounding text/labels manually to avoid duplicate headings, then hand-write the marker pair; the script replaces the content and heading between the markers.</p><p>It replaces that directive with the rendered content, wrapped in sentinel HTML comments:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- AUTO-GENERATED: mode_requirements_fixed_wing_manual --&gt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Mode Requirements</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-light-text-decoration:underline;--shiki-dark:#79B8FF;--shiki-dark-text-decoration:underline;">\`mode_req_manual_control\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">xxx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) - Requires stick input</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- END AUTO-GENERATED: mode_requirements_fixed_wing_manual --&gt;</span></span></code></pre></div><p>On subsequent runs the sentinels are detected and the content between them is updated in-place, so the script is safe to re-run whenever <code>mode_requirements.cpp</code> changes.</p><p><strong>Do not edit the text between the sentinel comments manually</strong> — it will be overwritten on the next run. Make changes in <code>requirement_defns.json</code> or in <code>mode_requirements.cpp</code>.</p><h2 id="path-calculation" tabindex="-1">Path Calculation <a class="header-anchor" href="#path-calculation" aria-label="Permalink to &quot;Path Calculation&quot;">​</a></h2><p>The script resolves the repository root at runtime using <code>Path(__file__).resolve()</code> and navigating <strong>three</strong> parent directories up:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/scripts/get_mode_requirements/get_mode_requirements.py</span></span>
<span class="line"><span>  -&gt; docs/scripts/get_mode_requirements/   (parent)</span></span>
<span class="line"><span>  -&gt; docs/scripts/                         (parent.parent)</span></span>
<span class="line"><span>  -&gt; docs/                                 (parent.parent.parent)</span></span>
<span class="line"><span>  -&gt; PX4-Autopilot/                        (parent.parent.parent.parent)  ← repo root</span></span></code></pre></div><p>If this script is ever moved, update the <code>repo_root</code> line accordingly.</p><h2 id="adding-or-changing-requirement-definitions" tabindex="-1">Adding or Changing Requirement Definitions <a class="header-anchor" href="#adding-or-changing-requirement-definitions" aria-label="Permalink to &quot;Adding or Changing Requirement Definitions&quot;">​</a></h2><p><code>requirement_defns.json</code> (in the same directory as the script) maps each <code>mode_req_*</code> flag name to a human-readable <code>text</code>, an example <code>sensor</code>, and an extended <code>detail</code> string. Add new entries here when new requirement flags are introduced in <code>mode_requirements.cpp</code>.</p><p>If the script encounters a flag in <code>mode_requirements.cpp</code> that has no entry in <code>requirement_defns.json</code>, it prints a <code>WARNING:</code> line to stderr and continues with empty <code>text</code>, <code>sensor</code>, and <code>detail</code> strings. If the JSON file is missing or malformed the script exits immediately with a clear <code>ERROR:</code> message.</p><h2 id="nav-state-vehicle-type-metadata" tabindex="-1">Nav-State / Vehicle-Type Metadata <a class="header-anchor" href="#nav-state-vehicle-type-metadata" aria-label="Permalink to &quot;Nav-State / Vehicle-Type Metadata&quot;">​</a></h2><p><code>mode_nav_state_defns.json</code> (in the same directory as the script) maps every <code>(VEHICLE_TYPE_*, NAVIGATION_STATE_*)</code> pair to display metadata used when generating <code>mode_requirements.md</code> section headings and controlling per-mode warning behaviour.</p><p>Each entry may contain:</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>label</code></td><td>string</td><td>—</td><td>Human-readable mode name (e.g. <code>&quot;Mission Mode&quot;</code>)</td></tr><tr><td><code>doc</code></td><td>string</td><td>—</td><td>Relative doc path used as a heading hyperlink (e.g. <code>&quot;../flight_modes_fw/mission.md&quot;</code>)</td></tr><tr><td><code>warn</code></td><td>bool</td><td><code>true</code></td><td>Set to <code>false</code> to suppress warnings for this mode</td></tr><tr><td><code>status</code></td><td>string</td><td>—</td><td>Short implementation-status note, used only when <code>doc</code> is absent (see below)</td></tr></tbody></table><p><strong>Heading generation</strong> (in <code>mode_requirements.md</code>): A mode is only given a full heading + requirement list in the main per-vehicle-type list if it has a <code>doc</code>. Modes with no <code>doc</code> are <strong>not</strong> given a bare heading in the main list — instead they are collected into a trailing <code>### Modes Without a Dedicated Page</code> summary for that vehicle type, rendered as <code>- **NAV_STATE** — {status}</code>. Use <code>status</code> to explain <em>why</em> there&#39;s no dedicated page — e.g. the mode isn&#39;t implemented for this vehicle type, or it behaves identically to another mode already documented, or it&#39;s an internal/failsafe state that isn&#39;t user-selectable. If a no-doc mode has no <code>status</code> text, the script prints a <code>WARNING:</code> to stderr and falls back to &quot;Not currently documented.&quot;</p><p><strong>Skipping snippet injection:</strong> if an entry has <code>&quot;warn&quot;: false</code> and no <code>&quot;doc&quot;</code> key, the script skips snippet processing for that mode without printing a warning. Use this for modes that are not real operational modes (e.g. <code>TERMINATION</code>) or that deliberately have no doc page. (This is orthogonal to <code>status</code>: <code>warn</code>/<code>doc</code> control snippet-injection behaviour, while <code>status</code> controls what&#39;s shown in the <code>mode_requirements.md</code> summary.)</p><p>If the script encounters a <code>(vehicle_type, nav_state)</code> pair that has no entry at all in <code>mode_nav_state_defns.json</code>, it prints a <code>WARNING:</code> line to stderr. Add a new entry whenever a new navigation state is introduced in <code>mode_requirements.cpp</code>.</p><p><strong>Ordering:</strong> the key order of <code>NAVIGATION_STATE_*</code> entries within each vehicle-type block in <code>mode_nav_state_defns.json</code> — not the order <code>setRequirement()</code> calls appear in <code>mode_requirements.cpp</code> — determines the order modes are rendered in <code>mode_requirements.md</code>, for both the headed list and the trailing &quot;Modes Without a Dedicated Page&quot; summary. The intended order is low-to-high autonomy (e.g. <code>MANUAL</code> → <code>STAB</code> → <code>ACRO</code> → ... → <code>OFFBOARD</code>). <code>VEHICLE_TYPE_FIXED_WING</code> and <code>VEHICLE_TYPE_ROTARY_WING</code> are separate JSON objects, so keep their key order in sync manually when adding or reordering a mode. Any nav_state the parser finds that has no entry at all in <code>mode_nav_state_defns.json</code> is appended after all JSON-ordered modes (in addition to the existing &quot;no entry&quot; warning).</p><p>The same principle applies one level up: the <strong>top-level</strong> key order of <code>mode_nav_state_defns.json</code> (currently <code>VEHICLE_TYPE_FIXED_WING</code> before <code>VEHICLE_TYPE_ROTARY_WING</code>) determines the order the <code>## Fixed-wing</code> / <code>## Multicopter</code> sections are rendered in <code>mode_requirements.md</code>. This is deliberate — vehicle types are discovered from <code>mode_requirements.cpp</code> into a Python <code>set</code>, whose iteration order is randomized per-process, so the render loops must never iterate that set/dict directly or the section order will vary between runs for no code reason. Any vehicle type found in the C++ but absent from the JSON is appended afterwards in sorted order.</p><h2 id="parser-design" tabindex="-1">Parser design <a class="header-anchor" href="#parser-design" aria-label="Permalink to &quot;Parser design&quot;">​</a></h2><p><code>parse_requirements()</code> uses a single-pass token scanner. A single compiled regex (<code>_TOKEN</code>) identifies all meaningful tokens in the <code>getModeRequirements()</code> body in left-to-right order: single-line comments (skipped), <code>if (vehicle_type == X) {</code> (push condition), <code>} else {</code> (flip condition), <code>}</code> (pop), <code>{</code> (push None for non-conditional blocks), and <code>setRequirement(…)</code> calls. A condition stack tracks the innermost active vehicle-type condition; requirements are assigned to the appropriate vehicle-type set based on whether we are inside an if-branch, an else-branch, or unconditional code.</p><p>This replaces an earlier two-pass regex approach that was fragile: its non-greedy <code>[\\s\\S]*?</code> pattern would span across unrelated blocks when a standalone <code>if</code> appeared before an <code>if-else</code>, producing silently wrong output for several modes.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>The test suite lives in <code>tests/</code> and is a pytest regression suite that guards against unintended changes to the parser output. It compares the live output of the parser against golden JSON snapshots:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tests/</span></span>
<span class="line"><span>  __init__.py</span></span>
<span class="line"><span>  test_get_mode_requirements.py   ← the test module</span></span>
<span class="line"><span>  test_data/</span></span>
<span class="line"><span>    requirement_defns_golden.json ← expected requirement_defns contents</span></span>
<span class="line"><span>    vehicle_modes_golden.json     ← expected parse_requirements() output</span></span></code></pre></div><ul><li><code>test_data/requirement_defns_golden.json</code> — expected contents of the <code>requirement_defns</code> dict (flag name → text / sensor / detail).</li><li><code>test_data/vehicle_modes_golden.json</code> — expected output of <code>parse_requirements()</code> applied to the checked-in <code>mode_requirements.cpp</code>: a per-vehicle-type, per-mode mapping of sorted requirement flag names.</li></ul><p><code>conftest.py</code> at the package root adds this directory to <code>sys.path</code> so pytest can import <code>get_mode_requirements</code> without any install step.</p><p>The suite contains three tests:</p><table tabindex="0"><thead><tr><th>Test</th><th>What it checks</th></tr></thead><tbody><tr><td><code>test_requirement_defns_matches_golden</code></td><td><code>requirement_defns</code> exactly matches the golden snapshot</td></tr><tr><td><code>test_vehicle_modes_matches_golden</code></td><td><code>parse_requirements()</code> output matches the golden snapshot; prints a per-mode diff on failure</td></tr><tr><td><code>test_all_requirement_flags_are_defined</code></td><td>Every flag found in <code>mode_requirements.cpp</code> has an entry in <code>requirement_defns</code></td></tr></tbody></table><h3 id="running-the-tests" tabindex="-1">Running the tests <a class="header-anchor" href="#running-the-tests" aria-label="Permalink to &quot;Running the tests&quot;">​</a></h3><p>From this directory (<code>get_mode_requirements/</code>):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><h3 id="when-to-run-and-update" tabindex="-1">When to run and update <a class="header-anchor" href="#when-to-run-and-update" aria-label="Permalink to &quot;When to run and update&quot;">​</a></h3><p><strong>Run the tests</strong> whenever you change:</p><ul><li>the parser logic in <code>get_mode_requirements.py</code>, or</li><li><code>src/modules/commander/ModeUtil/mode_requirements.cpp</code>.</li></ul><p><strong>Update the golden files</strong> after any intentional change to either of the above so that the snapshots stay in sync with the new expected output:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/test_get_mode_requirements.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update-golden</span></span></code></pre></div><p>Then re-run the tests to confirm they pass, and commit the updated golden files alongside the parser or C++ changes.</p>`,52)])])}const u=t(a,[["render",i]]);export{m as __pageData,u as default};
